  `cost` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '消耗',
  `installed_num` int NOT NULL DEFAULT '0' COMMENT '新增安装数',
  `installed_revenue` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收',
  `installed_revenue_1` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(次日)',
  `installed_revenue_2` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(2日)',
  `installed_revenue_3` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(3日)',
  `installed_revenue_4` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(4日)',
  `installed_revenue_5` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(5日)',
  `installed_revenue_6` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(6日)',
  `installed_revenue_7` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(7日)',
  `installed_revenue_14` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(14日)',
  `installed_revenue_30` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '新增回收(30日)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_app_date` (`app_code`,`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='回收率';


