CREATE TABLE `app_media_app` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '代码位创建-应用',
  `app_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '系统应用标识',
  `account_id` int NOT NULL DEFAULT '0' COMMENT '所属账号',
  `app_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用ID',
  `platform` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台',
  `app_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用名称',
  `package_name` varchar(230) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '包名',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
