  `platform` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '投放平台',
  `launch_type` tinyint(1) NOT NULL DEFAULT '-1' COMMENT '投放方式',
