CREATE TABLE `app_middle_device_ecpm` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `date` date NOT NULL COMMENT '日期',
  `ecpm_step` int NOT NULL DEFAULT '0' COMMENT 'ecpm 步长',
  `hour_step` int NOT NULL DEFAULT '0' COMMENT '小时步长',
  `vendor` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '厂商',
  `ad_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '广告类型',
  `times` int NOT NULL DEFAULT '0' COMMENT '展示次数',
  `device_num` int NOT NULL DEFAULT '0' COMMENT '用户数',
