CREATE TABLE `app_middle_live` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用标识',
  `date` date NOT NULL COMMENT '日期',
  `channel` int unsigned NOT NULL DEFAULT '0' COMMENT '渠道',
  `version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'APP版本',
  `os_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '系统版本',
  `vendor` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '生产厂商',
  `type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '统计类型:[installed][dau]',
  `device_num` int NOT NULL DEFAULT '0' COMMENT '设备数',
  `live_time` bigint NOT NULL DEFAULT '0' COMMENT '累积时间【毫秒】',
  PRIMARY KEY (`id`),
  KEY `idx_date_app` (`date`,`app_code`)
