  `app_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '媒体应用名',
  `placement_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代码位ID',
  `placement_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代码位类型',
  `placement_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代码位名',
  `ecpm` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '千次人均展示单价',
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态[1]启用[2]暂停或其他',
  `bidding` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否bidding',
  `created_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_placement` (`placement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='媒体-广告位';


CREATE TABLE `media_daily_app` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL COMMENT '日期',
  `media_type` json DEFAULT NULL COMMENT '已更新媒体',
  `total_cost` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '消耗',
  `media_revenue` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '媒体收入',
  `total_revenue` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '毛利收入',
  `detail` json DEFAULT NULL COMMENT '收入明细',
  `other_revenue` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '余量收入',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_date` (`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE `media_daily_company` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL COMMENT '日期',
  `total_revenue` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '总收入',
  `detail` json DEFAULT NULL COMMENT '主体收入明细',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_date` (`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE `media_daily_lianyun` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL COMMENT '日期',
  `media_type` json DEFAULT NULL COMMENT '已更新媒体',
  `total_cost` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '消耗',
  `media_revenue` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '媒体收入',
  `total_revenue` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '毛利收入',
  `detail` json DEFAULT NULL COMMENT '收入明细',
  `other_revenue` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '余量收入',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_date` (`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE `media_income` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用标识',
  `date` date DEFAULT NULL COMMENT '日期',
  `media_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '媒体类型',
  `media_company` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '媒体主体ID',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '媒体应用ID',
  `app_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '媒体应用名',
  `placement_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代码位ID',
  `placement_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代码位类型',
  `placement_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代码位名',
  `revenue` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '回收金额',
  `ecpm` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '千次人均展示单价',
  `request` int unsigned NOT NULL DEFAULT '0' COMMENT '请求数',
  `fill` int unsigned NOT NULL DEFAULT '0' COMMENT '填充数',
  `show` int unsigned NOT NULL DEFAULT '0' COMMENT '展示数',
  `click` int unsigned NOT NULL DEFAULT '0' COMMENT '点击数',
  `created_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_date_placement` (`date`,`placement_id`),
  KEY `idx_created_time` (`created_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='媒体-回收';


CREATE TABLE `mkt_account` (
  `account_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '帐户ID',
  `account_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '帐户名',
  `account_role` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '帐户角色',
  `is_valid` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '授权有效性[0]不可用[1]可用',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '授权用户ID',
  `updated_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `created_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-授权帐户';


CREATE TABLE `mkt_ad` (
  `ad_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '广告ID',
  `ad_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '广告名称',
  `advertiser_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `project_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '项目ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用',
  `put_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '投放状态 0-默认 1-投放中 2-暂停',
  `create_time` datetime DEFAULT NULL COMMENT '计划创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '计划修改时间',
  `budget_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '预算金额',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  `deleted_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  `is_mark` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否标记:[0]未标记[1]已标记',
  PRIMARY KEY (`ad_id`),
  KEY `idx_project` (`project_id`),
  KEY `idx_advertiser` (`advertiser_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-广告';


CREATE TABLE `mkt_advertiser` (
  `advertiser_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `advertiser_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '广告主名称',
  `agency_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代理名称',
  `platform` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '投放平台',
  `account_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '帐户ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '所属应用',
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态 1-正常 0-禁用',
  `launch_type` tinyint NOT NULL DEFAULT '0' COMMENT '投放方式0-次留双出 1-关键行为',
  `alert_status` tinyint DEFAULT '0' COMMENT '报警状态: 0=未知, 1=正常, 2=报警',
  `active_type` tinyint NOT NULL DEFAULT '0' COMMENT '激活类型[1]开屏[2]归因[3]回收[4]自定义',
  `active_value` json DEFAULT NULL COMMENT '激活定义设置',
  `action_type` tinyint NOT NULL DEFAULT '0' COMMENT '关键行为类型[0]不触发[1]回收率[2]加桌[3]自定义',
  `action_value` json DEFAULT NULL COMMENT '关键行为定义',
  `action_revenue` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '关键行为:回收率、回收金额',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `deleted_time` int NOT NULL DEFAULT '0' COMMENT '删除时间 0-未删除',
  `is_mark` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否标记:[0]未标记[1]已标记',
  `extra` json DEFAULT NULL COMMENT '额外配置',
  `notify_discount` tinyint(1) NOT NULL DEFAULT '0' COMMENT '扣量百分比',
  `keep_type` tinyint NOT NULL DEFAULT '0' COMMENT '留存定义[0]自然日[1]24小时',
  `notify_fill` tinyint(1) NOT NULL DEFAULT '0' COMMENT '被扣补量[0]否[1]是-留存满足',
  PRIMARY KEY (`advertiser_id`),
  KEY `idx_app` (`app_code`),
  KEY `idx_account` (`account_id`),
  KEY `idx_agency` (`agency_name`),
  KEY `idx_alert_status` (`alert_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-广告主';


CREATE TABLE `mkt_alert_delegate` (
  `delegate_id` bigint NOT NULL COMMENT '配置ID',
  `delegate_name` varchar(255) NOT NULL COMMENT '代投名称',
  `ding_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '钉钉token',
  `ding_secret` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '钉钉secret',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 0=禁用 1=启用',
  `created_time` int NOT NULL COMMENT '创建时间',
  `updated_time` int NOT NULL COMMENT '更新时间',
  `deleted_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  PRIMARY KEY (`delegate_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='代投配置表';


CREATE TABLE `mkt_alert_log` (
  `log_id` bigint NOT NULL COMMENT '日志ID',
  `rule_id` bigint NOT NULL COMMENT '规则ID',
  `item_type` varchar(20) NOT NULL COMMENT '类型 advertiser/project',
  `item_id` varchar(50) NOT NULL COMMENT '广告主ID/项目ID',
  `item_name` varchar(255) DEFAULT NULL COMMENT '名称',
  `trigger_data` json DEFAULT NULL COMMENT '触发时的数据',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '当前状态 0=正常 1=已触发',
  `notified_time` int DEFAULT NULL COMMENT '通知时间',
  `created_time` int NOT NULL COMMENT '创建时间',
  `updated_time` int NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`log_id`),
  KEY `idx_rule_id` (`rule_id`),
  KEY `idx_item` (`item_type`,`item_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='报警日志表';


CREATE TABLE `mkt_alert_rule` (
  `rule_id` bigint NOT NULL COMMENT '规则ID',
  `rule_name` varchar(255) NOT NULL COMMENT '规则名称',
  `rule_type` varchar(20) NOT NULL COMMENT '规则类型 advertiser/project',
  `app_code` json DEFAULT NULL COMMENT '应用代码',
  `rule_enable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '规则状态 0=关闭 1=开启',
  `threshold` json DEFAULT NULL COMMENT '阈值配置',
  `time_points` json DEFAULT NULL,
  `last_trigger_time` int DEFAULT NULL COMMENT '上次触发时间',
  `created_time` int NOT NULL COMMENT '创建时间',
  `updated_time` int NOT NULL COMMENT '更新时间',
  `deleted_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  PRIMARY KEY (`rule_id`),
  KEY `idx_rule_type` (`rule_type`),
  KEY `idx_rule_enable` (`rule_enable`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='报警规则表';


CREATE TABLE `mkt_alert_rule_delegate` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `rule_id` bigint NOT NULL COMMENT '规则ID',
  `delegate_id` bigint NOT NULL COMMENT '代投配置ID',
  PRIMARY KEY (`id`),
  KEY `idx_rule_id` (`rule_id`),
  KEY `idx_delegate_id` (`delegate_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='规则代投关联表';


CREATE TABLE `mkt_app` (
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用ID',
  `app_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用名',
  `app_secret` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用密钥',
  `platform` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开放平台',
  `auth_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '授权地址',
  `login_account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '登陆账号',
  `updated_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `created_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`app_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-开放平台应用';


CREATE TABLE `mkt_auto_app_log_v2` (
  `log_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NOT NULL DEFAULT '0' COMMENT '计划id',
  `begin_time` int NOT NULL DEFAULT '0' COMMENT '开始时间',
  `end_time` int NOT NULL DEFAULT '0' COMMENT '结束时间',
  `schedule_log` json DEFAULT NULL COMMENT '日志内容',
  `plan_snapshoot` json DEFAULT NULL COMMENT '计划快照',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='投放自动计划任务日志';


CREATE TABLE `mkt_auto_app_v2` (
  `plan_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plan_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '计划名称',
  `app_code` json DEFAULT NULL COMMENT '应用',
  `plan_enable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '计划是否开启:[0]关闭[1]启用',
  `threshold` json DEFAULT NULL COMMENT '阈值规则',
  `execute_operate` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '执行操作:[close_plan]关闭计划[empty_ad]拉空',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  PRIMARY KEY (`plan_id`),
  KEY `idx_plan_status` (`plan_enable`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='投放自动计划任务';


CREATE TABLE `mkt_auto_plan` (
  `plan_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plan_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '计划名称',
  `advertisers` json DEFAULT NULL COMMENT '广告主ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '应用',
  `plan_enable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '计划是否开启:[0]关闭[1]启用',
  `plan_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '计划运行状态:[0]待运行[1]运行中',
  `last_start_time` int NOT NULL DEFAULT '0' COMMENT '上次运行开始时间',
  `last_end_time` int NOT NULL DEFAULT '0' COMMENT '上次运行结束时间',
  `next_start_time` int NOT NULL DEFAULT '0' COMMENT '下次运行时间',
  `execute_times` int NOT NULL DEFAULT '0' COMMENT '运行次数',
  `execute_rule` json DEFAULT NULL COMMENT '计划规则',
  `threshold` json DEFAULT NULL COMMENT '阈值规则',
  `execute_operate` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '执行操作:[close_plan]关闭计划[empty_ad]拉空',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  `last_execute_result` tinyint(1) NOT NULL DEFAULT '1' COMMENT '上一次执行结果 0=失败',
  PRIMARY KEY (`plan_id`),
  KEY `idx_app_code` (`app_code`),
  KEY `idx_plan_status` (`plan_enable`,`plan_status`,`next_start_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='投放自动计划任务';


CREATE TABLE `mkt_auto_plan_log` (
  `log_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NOT NULL DEFAULT '0' COMMENT '计划id',
  `begin_time` int NOT NULL DEFAULT '0' COMMENT '开始时间',
  `end_time` int NOT NULL DEFAULT '0' COMMENT '结束时间',
  `schedule_log` json DEFAULT NULL COMMENT '日志内容',
  `plan_snapshoot` json DEFAULT NULL COMMENT '计划快照',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='投放自动计划任务日志';


CREATE TABLE `mkt_auto_plan_log_v2` (
  `log_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NOT NULL DEFAULT '0' COMMENT '计划id',
  `begin_time` int NOT NULL DEFAULT '0' COMMENT '开始时间',
  `end_time` int NOT NULL DEFAULT '0' COMMENT '结束时间',
  `schedule_log` json DEFAULT NULL COMMENT '日志内容',
  `plan_snapshoot` json DEFAULT NULL COMMENT '计划快照',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='投放自动计划任务日志';


CREATE TABLE `mkt_auto_plan_v2` (
  `plan_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plan_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '计划名称',
  `advertisers` json DEFAULT NULL COMMENT '广告主ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '应用',
  `plan_enable` tinyint(1) NOT NULL DEFAULT '0' COMMENT '计划是否开启:[0]关闭[1]启用',
  `plan_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '计划运行状态:[0]待运行[1]运行中',
  `last_start_time` int NOT NULL DEFAULT '0' COMMENT '上次运行开始时间',
  `last_end_time` int NOT NULL DEFAULT '0' COMMENT '上次运行结束时间',
  `threshold` json DEFAULT NULL COMMENT '阈值规则',
  `execute_operate` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '执行操作:[close_plan]关闭计划[empty_ad]拉空',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  `last_execute_result` tinyint(1) NOT NULL DEFAULT '1' COMMENT '上一次执行结果 0=失败',
  PRIMARY KEY (`plan_id`),
  KEY `idx_app_code` (`app_code`),
  KEY `idx_plan_status` (`plan_enable`,`plan_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='投放自动计划任务';


CREATE TABLE `mkt_notify` (
  `id` int NOT NULL AUTO_INCREMENT,
  `json` json DEFAULT NULL,
  `created_time` int DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE `mkt_plan` (
  `plan_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划ID',
  `advertiser_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用',
  `plan_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '计划名称',
  `put_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '投放状态 0-默认 1-投放中 2-暂停',
  `create_time` datetime DEFAULT NULL COMMENT '计划创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '计划修改时间',
  `budget_mode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '预算模式',
  `budget_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '预算金额',
  `schedule_start` datetime DEFAULT NULL COMMENT '投放开始',
  `schedule_end` datetime DEFAULT NULL COMMENT '投放结束',
  `schedule_time` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '投放时段 jl-48*7 ks-24*7',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  `deleted_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  `is_mark` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否标记:[0]未标记[1]已标记',
  PRIMARY KEY (`plan_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-计划';


CREATE TABLE `mkt_plan_rule` (
  `rule_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '计划监控规则',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '应用',
  `advertiser_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '广告主ID',
  `plan_ids` json DEFAULT NULL COMMENT '计划ID',
  `name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '规则名称',
  `cost` json DEFAULT NULL COMMENT '消耗设置',
  `cycle_day` int unsigned DEFAULT NULL COMMENT '周期（天）',
  `threshold` json DEFAULT NULL COMMENT '阀值设置',
  `execute_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '执行类型',
  `execute_value` json DEFAULT NULL COMMENT '执行参数',
  `execute_result` json DEFAULT NULL COMMENT '执行回执',
  `execute_times` int unsigned DEFAULT NULL COMMENT '执行次数',
  `execute_date` json DEFAULT NULL COMMENT '执行频次日期',
  `status` tinyint unsigned DEFAULT '1' COMMENT '状态 1-上架 0-下架',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `created_time` int unsigned DEFAULT NULL COMMENT '创建时间',
  `updated_time` int unsigned DEFAULT NULL COMMENT '修改时间',
  `deleted_time` int unsigned DEFAULT '0' COMMENT '删除时间',
  PRIMARY KEY (`rule_id`),
  KEY `idx_end_date` (`end_date`),
  KEY `idx_start_date` (`start_date`),
  KEY `idx_advertiser` (`advertiser_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-计划规则';


CREATE TABLE `mkt_plan_rule_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '计划监控执行记录',
  `rule_id` int DEFAULT NULL COMMENT '规则ID',
  `plan_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '计划ID',
  `rule_times` int DEFAULT NULL COMMENT '规则的第几个周期',
  `hit_threshold` json DEFAULT NULL COMMENT '命中的阀值',
  `rule_data` json DEFAULT NULL COMMENT '命中规则数据留存',
  `created_time` int DEFAULT NULL COMMENT '创建时间',
  `updated_time` int DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-计划规则命中纪录';


CREATE TABLE `mkt_project` (
  `project_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目ID',
  `advertiser_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用',
  `project_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '项目名称',
  `put_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '投放状态 0-默认 1-投放中 2-暂停',
  `alert_status` tinyint DEFAULT '0' COMMENT '报警状态: 0=未知, 1=正常, 2=报警',
  `create_time` datetime DEFAULT NULL COMMENT '项目创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '项目修改时间',
  `budget_mode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '预算模式',
  `budget_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '预算金额',
  `schedule_start` datetime DEFAULT NULL COMMENT '投放开始',
  `schedule_end` datetime DEFAULT NULL COMMENT '投放结束',
  `schedule_time` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '投放时段 jl-48*7 ks-24*7',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  `deleted_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  `is_mark` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否标记:[0]未标记[1]已标记',
  PRIMARY KEY (`project_id`),
  KEY `idx_alert_status` (`alert_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-计划';


CREATE TABLE `mkt_user` (
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户ID',
  `user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名',
  `user_email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户邮箱',
  `app_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用ID',
  `access_token` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '请求Token',
  `access_time` int unsigned NOT NULL DEFAULT '0' COMMENT 'Token过期时间',
  `refresh_token` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '刷新Token',
  `refresh_time` int unsigned NOT NULL DEFAULT '0' COMMENT '刷新过期时间',
  `updated_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `created_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放-授权用户';


CREATE TABLE `placement_csj` (
  `id` int NOT NULL AUTO_INCREMENT,
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `ad_unit_id` int NOT NULL DEFAULT '0' COMMENT '广告位 ID',
  `bidding_type` int NOT NULL DEFAULT '0' COMMENT '竞价类型',
  `ad_slot_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代码位ID',
  `ad_slot_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '代码位名称',
  `network` int NOT NULL DEFAULT '0' COMMENT '网络类型',
  `company_id` int NOT NULL DEFAULT '0' COMMENT '公司',
  `network_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '网络类型名称',
  `price` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '价格',
  `sort_type` int NOT NULL DEFAULT '0' COMMENT '排序方式',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `origin_type` int NOT NULL DEFAULT '0' COMMENT '渲染类型',
  `sub_ad_type` int NOT NULL DEFAULT '0' COMMENT '代码位类型',
  `smart_sort_switch` int NOT NULL DEFAULT '0' COMMENT '自动排序开关',
  `smart_sort_fetch_days` int NOT NULL DEFAULT '0' COMMENT '自动排序取数周期',
  `created_time` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='穿山甲绑定代码位';


CREATE TABLE `placement_csj_network` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL DEFAULT '0' COMMENT '所属公司id',
  `network_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'network名称',
  `network_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='穿山甲网络类型表';


