CREATE TABLE `report_daily_ad` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL COMMENT '日期',
  `advertiser_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `project_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '项目ID',
  `ad_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '广告ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用标识',
  `platform` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台jl-巨量 ks-快手',
  `cost` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '总花费',
  `show` int NOT NULL DEFAULT '0' COMMENT '展示数',
  `avg_show_cost` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '千次展示单价',
  `click` int NOT NULL DEFAULT '0' COMMENT '点击',
  `avg_click_cost` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '点击单价',
  `click_rate` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '点击率（点击/展示）',
  `convert` int NOT NULL DEFAULT '0' COMMENT '转化数',
  `convert_cost` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '转化成本',
  `convert_rate` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '转化率（转化/点击）',
  `active` int NOT NULL DEFAULT '0' COMMENT '激活数',
  `active_cost` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '激活成本',
  `active_rate` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '激活率（激活/点击）',
  `next_day_open` int NOT NULL DEFAULT '0' COMMENT '次留数',
  `next_day_open_cost` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '次留成本',
  `next_day_open_rate` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '次留率（次留/激活）',
  `key_action` int NOT NULL DEFAULT '0' COMMENT '关键行为数',
  `key_action_cost` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '关键行为成本',
  `key_action_rate` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '关键行为率（关键/激活）',
  `attribution_app_24h_roi` decimal(14,4) DEFAULT '0.0000' COMMENT '激活后24小时变现ROI',
  `hour_info` json DEFAULT NULL COMMENT '小时信息',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_date_id` (`date`,`ad_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='投放日报-广告';


CREATE TABLE `report_daily_ad_ext` (
  `id` bigint unsigned NOT NULL,
  `install_num` int unsigned NOT NULL DEFAULT '0' COMMENT '安装-数',
  `install_request` int unsigned NOT NULL DEFAULT '0' COMMENT '安装-请求',
  `install_fill` int unsigned NOT NULL DEFAULT '0' COMMENT '安装-填充',
  `install_fill_rate` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '安装-填充率%',
  `install_show` int unsigned NOT NULL DEFAULT '0' COMMENT '安装-展现',
  `install_show_rate` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '安装-展现率%',
