  `variable4` int NOT NULL DEFAULT '0' COMMENT '估算比例4日（%）',
  `variable5` int NOT NULL DEFAULT '0' COMMENT '估算比例5日（%）',
  `variable6` int NOT NULL DEFAULT '0' COMMENT '估算比例6日（%）',
  `variable7` int NOT NULL DEFAULT '0' COMMENT '估算比例7日（%）',
