  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_app` (`app_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='预估收益计算值比例';


