CREATE TABLE `user_account` (
  `user_id` bigint NOT NULL,
  `user_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `password` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '密码',
  `salt` varchar(13) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '盐',
  `is_super` tinyint NOT NULL DEFAULT '0' COMMENT '是否超级管理:1=是，0=否',
  `avatar` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '头像',
  `login_time` int NOT NULL DEFAULT '0' COMMENT '登陆时间',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '[0]冻结[1]正常',
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uniq_user_name` (`user_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户账号';


CREATE TABLE `user_app_relation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `app_id` int NOT NULL DEFAULT '0',
  `user_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户app关系表';


CREATE TABLE `user_role` (
  `role_id` int NOT NULL AUTO_INCREMENT,
  `role_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `pages` json DEFAULT NULL COMMENT '页面权限',
  `apis` json DEFAULT NULL COMMENT '接口权限',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  PRIMARY KEY (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='角色表';


CREATE TABLE `user_role_relation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `role_id` int NOT NULL DEFAULT '0',
  `user_id` bigint NOT NULL DEFAULT '0',
  `created_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_user_role` (`user_id`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户角色关系表';


